export type IconLevel = 'food' | 'sub-group' | 'group';
const cache = new Map<string, { key: string; level: IconLevel }>();

export function foodIcon(f: Pick<Food, 'name' | 'group' | 'sub'>): { key: string; level: IconLevel } {
  const id = f.group + '|' + f.sub + '|' + f.name;
  const hit = cache.get(id);
  if (hit) return hit;
  let r: { key: string; level: IconLevel };
  const rule = NAME_RULES.find(([g, re]) => g === f.group && re.test(f.name));
  if (rule) r = { key: rule[2], level: 'food' };
  else if (SUB_ICON[f.sub]) r = { key: SUB_ICON[f.sub], level: 'sub-group' };
  else r = { key: GROUP_ICON[f.group], level: 'group' };
  cache.set(id, r);
  return r;
}
